rgument\": [{\"id\": \"S001\", \"text\": \"Fix x∈V, r>0 and a spatial index j. By H002 every derivative entering u_t,u_tt,u_j,u_jj,u_jt is continuous and has derivatives of every order. Their finite sums and component products, in particular e and g_j, are jointly smooth by the usual finite differentiation rules.\", \"uses\": [\"H002\"], \"uses_local\": [], \"objects\": [\"u\", \"u_t\", \"u_tt\", \"u_j\", \"u_jj\", \"u_jt\", \"e\", \"e_t\", \"g\", \"A\", \"B\", \"T\", \"n\", \"m\", \"V\", \"W\", \"x\", \"r\", \"j\"], \"produces\": [{\"id\": \"F001\", \"statement\": \"For this fixed index j, u_t,u_tt,u_j,u_jj,u_jt and the scalar expressions e,g_j,A,B_j,T_j are jointly smooth on V×(0,∞).\", \"binders\": [], \"objects\": [\"u\", \"u_t\", \"u_tt\", \"u_j\", \"u_jj\", \"u_jt\", \"e\", \"e_t\", \"g\", \"A\", \"B\", \"T\", \"n\", \"m\", \"V\", \"W\", \"j\"], \"assumptions\": []}], \"introduces\": [], \"discharges\": []}, {\"id\": \"S002\", \"text\": \"Define U(y,ρ)=u(y,ρ) for ρ>0 and zero for ρ≤0. Near (x,r) it agrees with u since r>0. H002 gives that U is C^2 at this point. Apply M002 over R to U at (x,r), with smoothness order 2; the real minimum smoothness is 2. Evaluate the symmetric second derivative on the time direction (0,1) and the jth spatial coordinate direction. Coordinate directional derivatives are the corresponding partial derivatives, so ∂_r u_j(x,r)=∂_{x_j}u_t(x,r)=u_jt(x,r). This works at every positive time and point.\", \"uses\": [\"H002\", \"M002\"], \"uses_local\": [\"F001\"], \"objects\": [\"u\", \"u_t\", \"u_tt\", \"u_j\", \"u_jj\", \"u_jt\", \"e\", \"e_t\", \"g\", \"A\", \"B\", \"T\", \"n\", \"m\", \"V\", \"W\", \"x\", \"r\", \"j\", \"U\"], \"produces\": [{\"id\": \"F002\", \"statement\": \"For every y∈V, ρ>0 and 1≤i≤n, ∂_ρ u_i(y,ρ)=u_it(y,ρ), where u_it is the i-indexed member of u_jt.\", \"binders\": [{\"symbol\": \"y\", \"type\": \"point of V\"}, {\"symbol\": \"ρ\", \"type\": \"positive real\"}, {\"symbol\": \"i\", \"type\": \"integer with 1≤i≤n